  settings_search_idx_fda: 'macOS has revoked Xenon\'s Full Disk Access. It happens on every update, because the permission is tied to the app\'s signature. While it is missing, Xenon does not index your home folder: otherwise macOS would ask permission for Desktop, Documents, Downloads, Photos and Music on every pass. Turn it back on in System Settings → Privacy & Security → Full Disk Access: remove Xenon from the list and add it again.',
  disk_fda_title: 'macOS revoked one of Xenon\'s permissions',
  disk_fda_text: 'After every update macOS takes Full Disk Access away from Xenon. Without it the disk map and search stay empty. Turn it back on: remove Xenon from the list and add it again.',
  disk_fda_open: 'Open settings',
