  settings_hybrid_gpu_pause_hint: 'This PC has two graphics cards and Xenon draws on the integrated one, which has less headroom: the aurora, grid, animated background and small animations stay still, graphs step instead of gliding, and over a video or GIF wallpaper the Ambient clock is solid instead of glass. Switch it off to keep everything, at the cost of some frames',
  settings_bg_code_frozen_gpu: 'On this PC the background stops after a few seconds: it has two graphics cards and Xenon draws on the integrated one. This is not your code. You can change it with "Reduce animations on hybrid GPU", under Appearance, Surface.',
