  settings_bg_code_help_title: 'How to write the code',
  settings_bg_code_help_contract: 'Define a function draw(ctx, t, w, h): ctx is the canvas 2D context, t the elapsed seconds, w and h the size in pixels. It is called at the rate set in "Frames per second" (30 by default, up to 60) to paint one frame. Declare any particles or state with const/let above the function so they persist between frames.',
