  streaming_setup_discord: 'Create a Discord app (Developer Portal), add the redirect http://localhost under OAuth2, and paste its Client ID and Client Secret here. The Discord desktop client must be running.',
  streaming_discord_authorize: 'Open Discord and click "Authorize" in the pop-up that appears.',
  streaming_discord_notrunning: 'Discord desktop app not detected. Open Discord and try again.',
  streaming_discord_busy: 'Discord\'s local connection is busy (another app may be using it). Wait a moment and try Connect again.',
  streaming_discord_pipedenied: 'Discord is running as administrator, so Xenon is not allowed to talk to it. Quit Discord completely (tray icon → Quit) and reopen it normally, then press Connect. Waiting will not help.',
  streaming_discord_closed: 'Discord closed the connection. Check that the Client ID is correct and that Discord desktop is signed in with the account that created this application.',
  streaming_discord_denied: 'Authorization was denied in Discord. Approve the request, and make sure you are signed in with the account that owns this application.',
  streaming_discord_timeout: 'The authorization window timed out. Try again and click "Authorize" in Discord promptly.',
  streaming_token_failed: 'Login failed while exchanging the code. Check the Client Secret and that the redirect URL is exactly http://localhost.',
  streaming_discord_inflight: 'A login is already waiting for approval: look for the pop-up in Discord (or wait for it to time out) before trying again.',
  streaming_discord_badclientid: 'Discord rejected the Client ID. Copy the "Application ID" from your app\'s General Information page in the Developer Portal and re-enter it under Edit credentials.',
  streaming_discord_authfailed: 'Discord refused the authorization. The Discord desktop app must be signed in with the same account that owns this application in the Developer Portal.',
  streaming_discord_invalidscope: 'Discord rejected the requested permissions. The "rpc" access this needs is only granted to the account that OWNS the application (or one added under the app\'s OAuth2 testers): check which account the Discord desktop app is signed in with. Discord also refuses it if your app is an Activity (the "Embedded App" flag). The redirect is not involved in this error.',
  streaming_discord_badsecret: 'Discord rejected the Client Secret. Open your app in the Developer Portal, reset the secret, and paste the new value under Edit credentials.',
  streaming_discord_network: 'Discord authorized, but this PC could not reach discord.com to finish the login. Check VPN, firewall or proxy settings and try Connect again.',
  streaming_discord_id_shape: 'That doesn\'t look like a Discord Client ID: it\'s the long number labeled "Application ID" on your app\'s General Information page (not the Public Key or the Client Secret).',
