  'remote.intro_title': 'Secure remote PC control',
  'remote.intro_p1': 'Lets you access your PC desktop from a smartphone or tablet over your private Tailscale network (peer-to-peer VPN). Video streaming is handled by Sunshine; the free Moonlight client runs on your phone.',
  'remote.intro_p2': 'Sunshine and Tailscale are installed via winget (Microsoft\'s official package manager) directly from their official repositories.',
  'remote.intro_p3': 'The dashboard server is never exposed to the internet. The connection stays entirely inside your Tailscale network.',
  'remote.warnings_title': 'Before you proceed',
  'remote.warn_elevate': 'You will be asked to authorise the installation with your computer\'s password.',
  'remote.warn_macos_experimental': 'On macOS Sunshine is marked experimental by its own authors, and gamepads do not work.',
  'remote.intro_p2_linux': 'Sunshine is installed from Flathub, Tailscale from your distribution\'s official repositories.',
  'remote.intro_p2_mac': 'Sunshine and Tailscale are installed with Homebrew, from each project\'s official repositories.',
  'remote.warn_tailscale': 'You will need to sign in with your Tailscale account (free for personal use).',
  'remote.warn_pin': 'Moonlight will show a pairing PIN to enter here.',
