  ra_notif_err_too_many: 'Too many devices are subscribed. Remove one before adding another.',
  ra_notif_err_failed: 'That did not work. Check you are on the secure address and try again.',
  ra_notif_third_party: 'Notifications travel through your phone\'s push service (Apple, Google or Mozilla). There is no other way for them to work, and it is why they cost no battery. The text is encrypted, so they move bytes they cannot read. It is the one thing in Xenon that goes out to somebody else, and it stays off until you turn it on.',
