  ra_https_hint: 'Goes over Tailscale with HTTPS. Unlocks the installable app on your phone, the microphone and notifications, and the address stops changing when your router changes its mind.',
  ra_https_url: 'Secure address',
  ra_https_pair_note: 'With this on it is the only address you need: it works at home and away. Devices paired on the local address have to be paired again here: a browser ties the pairing to the address.',
  ra_https_why_not_installed: 'Tailscale is not installed on this PC.',
