  xfer_help_to_pc_1: 'On this PC: Settings → Phone → Add device. Point the phone\'s camera at the QR code.',
  xfer_help_to_pc_2: 'The code opens Xenon in the phone\'s browser. Add it to the home screen and it becomes an icon you can reopen any time.',
  xfer_help_to_pc_3: 'In Xenon on the phone, tap Send to PC in the bottom bar, then Photos and videos or Other files.',
  xfer_help_to_phone: 'From this PC to your phone',
  xfer_help_to_phone_1: 'Drag files in here, or use the two buttons below.',
  xfer_help_to_phone_2: 'In Xenon on the phone, tap Download on the file\'s row.',
  xfer_help_where: 'Arriving files are copied into Download\\Xenon. Change the folder in Settings → Phone.',
  xfer_note_lan: 'It works while the phone and the PC are on the same network, or on Tailscale.',
  xfer_note_ios: 'On iPhone you have to open Xenon to send something. The iOS Share button cannot send to Xenon.',
  xfer_note_ios_save: 'A downloaded file goes to Files, not the camera roll. For a photo, press and hold it and choose Add to Photos.',
  xfer_note_limits: 'One file at a time, one after the other. If you close Xenon halfway, that file starts over.',
