  ra_guide_open: 'Step-by-step guide',
  ra_guide_title: 'Set up your phone, step by step',
  ra_guide_close: 'Close the guide',
  ra_guide_sub: 'Steps 1 to 3 put the dashboard on your phone at home. The rest is only needed if you want it to work away from home too.',
  ra_guide_group_home: 'At home, on your own Wi-Fi',
  ra_guide_group_away: 'Away from home (optional)',
  ra_guide_ack: 'Done',
  ra_guide_undo: 'Not done yet',
  ra_guide_s1: 'Turn on access from other devices',
  ra_guide_s1_body: 'It is off until you turn it on. While it is off, Xenon answers this PC and nothing else.',
  ra_guide_s2: 'Point your phone at the QR code',
  ra_guide_s2_body: 'The code is an invitation, not a password: it lasts three minutes and stops working after a few wrong tries. The dashboard opens in the phone browser. There is nothing to install on the phone.',
  ra_guide_s2_wait: 'Available once the switch above is on.',
  ra_guide_s3: 'Add it to the phone home screen',
  ra_guide_s3_body: 'On iPhone open Share and then Add to Home Screen. On Android, Chrome offers to install it. Xenon then opens with its own icon, full screen, and the microphone and notifications work there.',
  ra_guide_s4: 'Turn on the secure address',
  ra_guide_s4_body: 'This gives this PC a name of its own that works from anywhere, over an encrypted connection. It uses Tailscale, which is free, and Xenon installs and signs in to it for you. You are not creating an account with Xenon.',
  ra_guide_s5: 'Turn on HTTPS certificates in your Tailscale account',
  ra_guide_s5_body: 'This is the one step Xenon cannot do for you. Open the Tailscale admin console, scroll to HTTPS Certificates and press Enable. It is free on every plan. Then come back here: Xenon has carried on waiting.',
  ra_guide_s6: 'Install Tailscale on the phone, same account',
  ra_guide_s6_body: 'Get it from the App Store or Google Play, sign in with the same account you just used, and turn its switch on. This is the step people forget. When it is missing the phone says it cannot open the address at all: nothing is broken, that address only exists inside your own network.',
  ra_guide_s7: 'Pair the phone again on the new address',
  ra_guide_s7_body: 'Press Add device in step 2 and scan again. The browser ties a pairing to the address it was made on, so a phone paired on the home address is not paired on the secure one. After this you only need the new address, at home and away.',
  ra_guide_done_title: 'That is the setup done',
  ra_guide_done_body: 'Your phone is paired. Last thing: should Xenon keep opening on this PC as well?',
  ra_guide_keep: 'Keep it here too',
  ra_guide_hide: 'Hide Xenon on this PC',
  ra_guide_hide_note: 'Hiding it stops Xenon opening on this PC, at login too. It keeps running in the background, so the phone keeps working. Bring the window back from the Xenon icon next to the clock, or from Settings, then Display.',
  ra_guide_hide_browser: 'This is the dashboard in a browser, so there is no window to hide. In the Xenon app you can also choose to have it stop opening on this PC.',
